export const courageId = (number: StoryLessonNumber) => `conversational-skills-L8-C5-${number}-${courageEpisodes[number].skill}-en-v1`;

export function buildCourageLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildEnglishExpressionLesson(number, courageEpisodes[number], previous, reference, {
    id: courageId(number), chapterName: 'The Courage to Speak', pronunciation: couragePronunciation[number],
    setting: 'Aokawa, a fictional Tokyo neighbourhood. The podcast team regroups at the café and studio, takes part in a newly structured public forum and committee, and returns to ordinary community life one year after the podcast began.',
    previousSummary: index === 0 ? 'A misleading edit made and circulated outside the team has been corrected. Damage to Daisuke and the podcast remains, and releases have paused for three weeks.' : courageEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(8)}\nReference: The Things We Don’t Say, Chapter 5: The Courage to Speak, final chapter. Owner TOEIC 785–940 range and visible label. Eight episodes map to 1-4 and 6-9, with 5/10 dynamic checkpoints. English only, four Step A expressions, only Step B pronunciation with exact bold stress, no Part III or extra commentary. Objective first, plain situations, separate questions, direct tutor-first roles, short dialogue, private listening and fresh reading notes. No mandatory speech, new artwork, romance, external model API or AI credits. Use only supplied Chapter 5 opening: corrected misleading outsider edit/circulation, identity/method unspecified, three-week release pause and residual harm. Do not invent Chapter 4 events, lawsuits, apology outcomes or universal restored trust. Clearer guidelines/consent/correction process proposed; Riku asks affected people’s needs. Company rationale includes aging/maintenance/infrastructure and possible costs of inaction, not verified forecasts or full endorsement. New structured forum with Hana facilitation, Yuna affordability-near-work and Farah transparent applications. Participants agree to establish committee; no final affordability deal or carried-over recording permission from earlier forum. First committee meeting two weeks later, four hours; business priority only evaluated, eligibility not guaranteed. Exactly three immediate priorities: publish clearer information, assess relocation needs, formal resident response before final decisions. These are agreed priorities, not all tasks completed. Return episode has Yuna/Farah/Mr. Hayashi agreement and each reviewing intended use before publication; no invented statistics, equal-income comparison among actual guests, release date or sensational accusations. Months after forum company agrees detailed relocation assessment and start formal tenant consultations; project still under review, no proven completion of those commitments. Daisuke actually meets financial adviser, negotiates manageable lender repayment, obtains one-year existing lease extension while discussions continue. No debt forgiveness, numbers, permanent café security or public release of private finances. Nakahara arrives with group members for gathering, beyond earlier invitation interest, not guaranteed recovery or revenue. Friday final recording closes season one, not podcast forever; team reflections on follow-through, autonomy, editing and listening/silence, no new guest or exact release time. One year after first podcast episode, proposal revised after consultations, affordability/displacement concerns remain, committee regular, café open modest improvement partly from gatherings. Riku notes, Hana educational support-access materials with no invented qualification, Leila edits new community-initiative episode not confirmed released. New unnamed woman unsure about public disclosure is not identified as Akari or any earlier source. No private story given, recording/publication agreement or debt disclosed. Emi affirms story matters either way, woman leaves relieved, Emi returns to ordinary coffee-price disagreement without actual price increase confirmed. End with dignity, shared ongoing work and imperfect change, not universal agreement, completed development or sequel cliffhanger. All earlier confidentiality/refusal boundaries remain.`,
  });
  lesson.storyData.storyTitle = 'The Things We Don’t Say';
  lesson.storyData.characters = [
    { id: 'emi', name: 'Emi Sato', role: 'main', description: 'Podcast journalist who rebuilds practice around listening, accountability and a participant’s freedom to choose public sharing or privacy.' },
    { id: 'riku', name: 'Riku', role: 'supporting', description: 'Community organiser who urges attention to affected people, helps establish the committee and values follow-through after identifying a problem.' },
    { id: 'hana', name: 'Hana', role: 'supporting', description: 'Friend who facilitates the structured forum and later prepares educational support-access materials. No professional qualification is supplied.' },
    { id: 'leila', name: 'Leila', role: 'supporting', description: 'Producer who reviews intended use and the effects of editing, records the first-season reflection and later works on a new episode.' },
    { id: 'daisuke', name: 'Daisuke', role: 'supporting', description: 'Café owner who receives a one-year lease extension and manageable repayment arrangement, keeps improving the business and remains part of the friends’ ordinary disagreements.' },
    { id: 'fujimoto', name: 'Ms. Fujimoto', role: 'supporting', description: 'Development representative who explains economic reasoning, participates in the forum and committee, and acknowledges unresolved commitments.' },
    { id: 'yuna', name: 'Yuna', role: 'supporting', description: 'Supermarket worker who raises rent and location concerns and agrees to a reviewed contribution about daily decisions.' },
    { id: 'farah', name: 'Farah', role: 'supporting', description: 'Professional who advocates transparent rental requirements and agrees to discuss fair treatment beyond obtaining one apartment.' },
    { id: 'hayashi', name: 'Mr. Hayashi', role: 'supporting', description: 'Earlier career-transition interviewee who agrees to a reviewed contribution about changing careers later in life.' },
    { id: 'nakahara', name: 'Mr. Nakahara', role: 'supporting', description: 'Retired resident who now arrives at the café with members of his community group for their gathering.' },
    { id: 'visitor', name: 'The visitor', role: 'supporting', description: 'Unnamed woman who asks whether her experience matters while remaining undecided about public sharing. Emi offers reassurance without demanding disclosure.' },
  ];
  return { ...lesson, course: 'conversational-skills', level: 8, chapter: 5, lessonNumber: number,
    levelBadge: 'TOEIC 785–940', chapterLabel: 'Chapter 5: The Courage to Speak', status: previous.status || 'draft',
    overlayColor: previous.overlayColor || '#17252bcc', supportLanguage: 'en', authoringLanguageTarget: 'TOEIC 785-940', authoringLanguageRevision: 'toeic-v1' };
}

export function buildCourageChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildCourageLesson(number, {}, reference));
}
